const saved = await tools.capability_save({
  name: "libero_soup_to_basket",
  layer: "recipe",
  description:
    "Place an alphabet soup can into a basket using the body's libero_pick_place skill. Predicts a fresh receipt from args, runs it, polls the same Job until terminal, and returns the job id with the three terminal fields, throwing when state/goalStatus/stopStatus are not all successful.",
  requires:
    "Body supports libero_pick_place; ego_state contains the can and the basket with usable ES references.",
  ensures:
    "Returns { job, state, goalStatus, stopStatus, evidence } with state=succeeded, goalStatus=achieved, stopStatus=confirmed; otherwise throws an Error containing the job result. No automatic retry.",
  parameters: {
    target: "ES reference of the alphabet soup can to pick",
    on: "ES reference of the basket to place it into",
  },
  code: `const target = args.target;
const on = args.on;
if (!target || !on) throw new Error("libero_soup_to_basket requires args.target and args.on");

const pred = await tools.ego_predict({ skill: "libero_pick_place", target, on });
if (pred.feasible !== true || pred.withinRiskLimit !== true) {
  throw new Error("libero_pick_place not feasible: " + JSON.stringify({ feasible: pred.feasible, withinRiskLimit: pred.withinRiskLimit, issues: pred.issues, risk: pred.risk }));
}

const run = await tools.skill_run({ receipt: pred.receipt, wait: true, timeoutS: 240 });
const jobId = run.job ?? run.jobId ?? run.id;
if (!jobId) throw new Error("skill_run returned no job: " + JSON.stringify(run));

let last = run;
let polls = 0;
while (last.state === "running" || last.state === "queued") {
  if (polls >= 60) break;
  await new Promise((r) => setTimeout(r, 5000));
  last = await tools.skill_status({ job: jobId });
  polls += 1;
}

const ok = last.state === "succeeded" && last.goalStatus === "achieved" && last.stopStatus === "confirmed";
if (!ok) {
  throw new Error("libero_pick_place did not reach success: " + JSON.stringify({ job: jobId, state: last.state, goalStatus: last.goalStatus, stopStatus: last.stopStatus, message: last.message, reasonCode: last.reasonCode, evidence: last.evidence }));
}
return { job: jobId, state: last.state, goalStatus: last.goalStatus, stopStatus: last.stopStatus, evidence: last.evidence };`,
});
